hints:
```
store counts for the smaller dimension
for each line in the other dimension:
    count servers in this line on the fly
    for each server in this line:
        if this line's count > 1 or stored count for its line > 1:
            increment result
return result
```

code.cpp:
class Solution {
public:
    int countServers(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size(), result = 0;
        if (m <= n) {
            vector<int> rowCount(m, 0);
            for (int i = 0; i < m; i++)
                for (int j = 0; j < n; j++)
                    rowCount[i] += grid[i][j];
            for (int j = 0; j < n; j++) {
                int colCount = 0;
                for (int i = 0; i < m; i++) colCount += grid[i][j];
                for (int i = 0; i < m; i++)
                    if (grid[i][j] && (colCount > 1 || rowCount[i] > 1)) result++;
            }
        } else {
            vector<int> colCount(n, 0);
            for (int i = 0; i < m; i++)
                for (int j = 0; j < n; j++)
                    colCount[j] += grid[i][j];
            for (int i = 0; i < m; i++) {
                int rowCount = 0;
                for (int j = 0; j < n; j++) rowCount += grid[i][j];
                for (int j = 0; j < n; j++)
                    if (grid[i][j] && (rowCount > 1 || colCount[j] > 1)) result++;
            }
        }
        return result;
    }
};
